-- Ordinary taken-leave pay authority. No migration of old text batch adoptions.
CREATE TABLE ty_lp_policy(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),stable_key text NOT NULL,revision integer NOT NULL CHECK(revision>0),system text NOT NULL CHECK(system IN('CN_PAYROLL','HK_PAYROLL')),currency text NOT NULL CHECK(currency IN('CNY','HKD')),valid_from date NOT NULL,valid_to date,data jsonb NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved')),created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),review_ref text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(company_id,stable_key,revision),CHECK(valid_to IS NULL OR valid_to>valid_from),CHECK((system='HK_PAYROLL')=(currency='HKD')),CHECK(status='draft' OR(approved_by IS NOT NULL AND approved_by<>created_by AND length(review_ref)>=4)));
CREATE TABLE ty_lp_parent(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),request_id bigint NOT NULL REFERENCES ty_leave_request(id),period date NOT NULL CHECK(extract(day FROM period)=1),head_revision integer NOT NULL DEFAULT 0,current_approved_id bigint,UNIQUE(request_id,period));
CREATE TABLE ty_lp_fact(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,parent_id bigint NOT NULL REFERENCES ty_lp_parent(id),revision integer NOT NULL CHECK(revision>0),policy_id bigint NOT NULL REFERENCES ty_lp_policy(id),system text NOT NULL,currency text NOT NULL,data jsonb NOT NULL,source_hash text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved')),created_by bigint NOT NULL REFERENCES sys_account(id),reviewed_by bigint REFERENCES sys_account(id),review_ref text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(parent_id,revision),CHECK(status='draft' OR(reviewed_by IS NOT NULL AND reviewed_by<>created_by AND length(review_ref)>=4)));
ALTER TABLE ty_lp_parent ADD FOREIGN KEY(current_approved_id)REFERENCES ty_lp_fact(id);
INSERT INTO ty_pay_item_catalog(code,name,system,category,unit,output_ledger,metadata)VALUES('LEAVE_GROSS_REDUCTION','假期待遇与已含正常工资差减','COMMON','personal_deduction','currency_amount','employee_gross_wage','{"employee_cash_wage_effect":"decrease_gross","cost_additive":false,"cash_component_nature":"verified_leave_gross_replacement","creates_additional_payable":false,"exclusion_group":"leave_pay_normal_coverage"}'::jsonb);
INSERT INTO ty_pay_item_catalog(code,name,system,category,unit,output_ledger,metadata)VALUES('LEAVE_PAY_RECONCILIATION','已核假期待遇工资','COMMON','cash_earnings','currency_amount','employee_gross_wage','{"employee_cash_wage_effect":"increase_gross","cost_additive":true,"cash_component_nature":"verified_leave_pay","creates_additional_payable":true}'::jsonb);
CREATE FUNCTION fn_ty_lp_current(fact_key bigint)RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=''AS $$
DECLARE f public.ty_lp_fact%ROWTYPE;p public.ty_lp_parent%ROWTYPE;r public.ty_leave_request%ROWTYPE;s public.ty_lp_policy%ROWTYPE;a public.ty_leave_account%ROWTYPE;l public.ty_leave_relationship%ROWTYPE;e public.ty_employment%ROWTYPE;BEGIN
 SELECT*INTO f FROM public.ty_lp_fact WHERE id=fact_key;SELECT*INTO p FROM public.ty_lp_parent WHERE id=f.parent_id;SELECT*INTO r FROM public.ty_leave_request WHERE id=p.request_id;SELECT*INTO s FROM public.ty_lp_policy WHERE id=f.policy_id;SELECT*INTO a FROM public.ty_leave_account WHERE id=r.account_id;SELECT*INTO l FROM public.ty_leave_relationship WHERE id=a.relationship_id;SELECT*INTO e FROM public.ty_employment WHERE id=r.employment_id;
 RETURN f.id IS NOT NULL AND f.status='approved'AND f.id=p.current_approved_id AND f.revision=p.head_revision AND s.status='approved'AND s.company_id=p.company_id AND s.system=f.system AND s.currency=f.currency AND r.status='taken'AND r.employment_id=p.employment_id AND l.person_id=p.person_id AND l.group_id=p.group_id AND e.company_id=p.company_id AND e.person_id=p.person_id AND(f.data->'request'->>'request_id')::bigint=r.id AND(f.data->'request'->>'scheme_id')::bigint=r.scheme_id AND(f.data->'request'->>'employment_id')::bigint=r.employment_id AND(f.data->'request'->>'quantity')::numeric=r.quantity AND(f.data->'request'->>'starts_at')::timestamptz=r.starts_at AND(f.data->'request'->>'ends_at')::timestamptz=r.ends_at AND f.data->'request'->'facts'=r.facts AND f.data->'request'->>'legal_employer_key'=l.legal_employer_key AND NOT EXISTS(SELECT 1 FROM public.ty_lp_policy newer WHERE newer.company_id=s.company_id AND newer.stable_key=s.stable_key AND newer.status='approved'AND newer.revision>s.revision AND newer.valid_from<=(f.data->'days'->0->>'date')::date AND(newer.valid_to IS NULL OR newer.valid_to>(f.data->'days'->0->>'date')::date));
END;$$;
CREATE FUNCTION fn_ty_lp_amount_data(d jsonb,part text)RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path=''AS $$DECLARE x jsonb;daily numeric;units numeric;total numeric:=0;v numeric;net numeric;benefit text;offset_days integer;BEGIN
 IF part NOT IN('pay','reduction')OR NOT(d->'eligibility'@>'{"actual_taken_verified":true,"no_duplicate_payment_verified":true}'::jsonb)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='实际已休和防重复事实待核';END IF;
 benefit=d->'policy'->>'benefit';
 IF benefit IN('CN_UNPAID','HK_UNPAID')THEN IF NOT(d->'eligibility'@>'{"lawful_unpaid_verified":true}'::jsonb)OR d->'basis'->>'mode'<>'verified_unpaid'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='未知待遇不可当零工资无薪假';END IF;
 ELSIF benefit LIKE'CN_%'THEN IF NOT(d->'eligibility'@>'{"eligibility_verified":true}'::jsonb)OR length(coalesce(d->'eligibility'->>'locality',''))<2 OR length(coalesce(d->'eligibility'->>'local_rule_ref',''))<4 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='内地地方及待遇适用仍待核';END IF;
 ELSE IF NOT(d->'eligibility'@>'{"continuous_contract_verified":true}'::jsonb)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='香港连续合约资格待核';END IF;
 IF benefit='HK_ANNUAL'AND NOT(d->'eligibility'@>'{"paid_entitlement_verified":true}'::jsonb)OR benefit='HK_SICK'AND(NOT(d->'eligibility'@>'{"sufficient_paid_sickness_verified":true,"medical_or_legal_proof_verified":true,"no_holiday_or_injury_compensation_overlap":true}'::jsonb)OR(coalesce((d->'eligibility'->>'consecutive_episode_days')::integer,0)<4 AND NOT coalesce((d->'eligibility'->>'pregnancy_examination_exception')::boolean,false)))OR benefit='HK_MATERNITY'AND NOT(d->'eligibility'@>'{"forty_weeks_verified":true,"pregnancy_notice_verified":true,"required_medical_proof_verified":true}'::jsonb)OR benefit='HK_PATERNITY'AND NOT(d->'eligibility'@>'{"forty_weeks_verified":true,"father_and_birth_document_verified":true,"document_deadline_verified":true,"notice_and_leave_window_verified":true}'::jsonb)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='香港法定给薪资格事实不完整';END IF;END IF;
 daily=(d->'basis'->'daily'->>'numerator')::numeric/(d->'basis'->'daily'->>'denominator')::numeric;IF(daily<=0 AND benefit NOT IN('CN_UNPAID','HK_UNPAID'))OR(d->>'normal_covered')::numeric<0 OR(d->>'benefit_covered')::numeric<0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='给薪基线和覆盖额必须明确非负';END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(d->'days')LOOP units=(x->'units'->>'numerator')::numeric/(x->'units'->>'denominator')::numeric;IF units<=0 OR units>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='实际给薪日数或排班比例不符';END IF;v=daily*(d->'policy'->>'rate')::numeric*units;IF d->'policy'->>'min_daily'IS NOT NULL THEN v=greatest(v,(d->'policy'->>'min_daily')::numeric*units);END IF;IF benefit='HK_MATERNITY'THEN offset_days=(x->>'date')::date-(d->'eligibility'->>'episode_start')::date;IF offset_days<0 OR offset_days>=98 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='产假须在已核14周内';END IF;IF offset_days>=70 THEN v=least(v,80000::numeric/28*units);END IF;END IF;total=total+v;END LOOP;
 IF benefit<>'CN_MATERNITY'AND(d->>'benefit_covered')::numeric<>0 OR(d->>'benefit_covered')::numeric>total THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='待遇抵扣性质或范围不符';END IF;
 net=total-(d->>'benefit_covered')::numeric-(d->>'normal_covered')::numeric;RETURN round(greatest(CASE part WHEN'pay'THEN net ELSE -net END,0),2);END;$$;
CREATE FUNCTION fn_ty_lp_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE p public.ty_lp_parent%ROWTYPE;r public.ty_leave_request%ROWTYPE;pol public.ty_lp_policy%ROWTYPE;e public.ty_employment%ROWTYPE;a public.ty_leave_account%ROWTYPE;l public.ty_leave_relationship%ROWTYPE;BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='假期给薪历史不可删除';END IF;
 IF TG_TABLE_NAME='ty_lp_parent'THEN SELECT*INTO r FROM public.ty_leave_request WHERE id=NEW.request_id;SELECT*INTO e FROM public.ty_employment WHERE id=r.employment_id;SELECT*INTO a FROM public.ty_leave_account WHERE id=r.account_id;SELECT*INTO l FROM public.ty_leave_relationship WHERE id=a.relationship_id;IF e.id IS NULL OR NEW.employment_id<>e.id OR NEW.person_id<>e.person_id OR NEW.company_id<>e.company_id OR NEW.group_id<>e.group_id OR l.person_id<>e.person_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='假期给薪须来自同人实际请假和雇佣';END IF;IF TG_OP='UPDATE'AND(to_jsonb(NEW)-ARRAY['head_revision','current_approved_id'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['head_revision','current_approved_id'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='给薪经济根不可换人换期';END IF;IF NEW.current_approved_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_lp_fact WHERE id=NEW.current_approved_id AND parent_id=NEW.id AND revision<=NEW.head_revision AND status='approved')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='当前给薪核定须属于当前根版本';END IF;RETURN NEW;END IF;
 IF TG_OP='UPDATE'AND(OLD.status='approved'OR(to_jsonb(NEW)-ARRAY['status','approved_by','reviewed_by','review_ref'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','approved_by','reviewed_by','review_ref']))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='给薪政策和核定正文不可覆盖，应追加版本';END IF;
 IF TG_TABLE_NAME='ty_lp_policy'THEN IF NEW.data->>'leave_code'='annual'AND NOT(NEW.system='HK_PAYROLL'AND NEW.data->>'benefit'='HK_ANNUAL'OR NEW.system='CN_PAYROLL'AND NEW.data->>'benefit'='CN_PAID')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已放年假须保留对应正常工资待遇，不能改为病假或无薪假';END IF;IF NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.company_id AND group_id=NEW.group_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='政策公司须属于同集团';END IF;IF NEW.data->>'benefit'IN('HK_ANNUAL','CN_PAID','CN_MATERNITY')AND(NEW.data->>'rate')::numeric<>1 OR NEW.data->>'benefit'IN('HK_SICK','HK_MATERNITY','HK_PATERNITY')AND(NEW.data->>'rate')::numeric<>0.8 OR NEW.data->>'benefit'IN('CN_UNPAID','HK_UNPAID')AND(NEW.data->>'rate')::numeric<>0 OR NEW.data->>'benefit'='CN_SICK'AND(coalesce((NEW.data->>'min_daily')::numeric,0)<=0 OR(NEW.data->>'rate')::numeric NOT BETWEEN 0 AND 1)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='法定给薪倍率或内地病假保障下限不符';END IF;IF NEW.status='approved'AND public.fn_ty_hr_same_human(NEW.created_by,NEW.approved_by)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='政策复核须不同自然人';END IF;END IF;
 IF TG_TABLE_NAME='ty_lp_fact'THEN SELECT*INTO p FROM public.ty_lp_parent WHERE id=NEW.parent_id;SELECT*INTO pol FROM public.ty_lp_policy WHERE id=NEW.policy_id;IF p.company_id<>pol.company_id OR NEW.system<>pol.system OR NEW.currency<>pol.currency OR NEW.data->'policy'IS DISTINCT FROM pol.data OR(NEW.data->>'target')::numeric IS DISTINCT FROM public.fn_ty_lp_amount_data(NEW.data,'pay')OR(NEW.data->>'reduction')::numeric IS DISTINCT FROM public.fn_ty_lp_amount_data(NEW.data,'reduction')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='假期待遇不能换主体或币种';END IF;IF NEW.status='approved'AND(public.fn_ty_hr_actor_is_person(NEW.reviewed_by,p.group_id,p.person_id)OR public.fn_ty_hr_same_human(NEW.created_by,NEW.reviewed_by))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='受益人不得核定本人给薪';END IF;END IF;RETURN NEW;END;$$;
CREATE TRIGGER ty_lp_policy_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_lp_policy FOR EACH ROW EXECUTE FUNCTION fn_ty_lp_guard();
CREATE TRIGGER ty_lp_parent_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_lp_parent FOR EACH ROW EXECUTE FUNCTION fn_ty_lp_guard();
CREATE TRIGGER ty_lp_fact_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_lp_fact FOR EACH ROW EXECUTE FUNCTION fn_ty_lp_guard();
CREATE FUNCTION fn_ty_lp_pay_key(batch_key bigint,adoption_key bigint)RETURNS text LANGUAGE plpgsql STABLE SET search_path=''AS $$DECLARE b public.ty_pay_batch%ROWTYPE;a public.ty_pay_adoption%ROWTYPE;f public.ty_lp_fact%ROWTYPE;p public.ty_lp_parent%ROWTYPE;o public.ty_pay_obligation%ROWTYPE;i public.ty_pay_item%ROWTYPE;part text;code text;rel public.ty_pay_config%ROWTYPE;BEGIN SELECT*INTO b FROM public.ty_pay_batch WHERE id=batch_key;SELECT*INTO a FROM public.ty_pay_adoption WHERE id=adoption_key AND batch_id=batch_key;SELECT*INTO f FROM public.ty_lp_fact WHERE id=split_part(a.source_id,':',1)::bigint;SELECT*INTO p FROM public.ty_lp_parent WHERE id=f.parent_id;SELECT*INTO o FROM public.ty_pay_obligation WHERE id=a.obligation_id;SELECT*INTO i FROM public.ty_pay_item WHERE adoption_id=a.id;part=split_part(a.source_id,':',2);code=CASE WHEN part='reduction'THEN'LEAVE_GROSS_REDUCTION'ELSE CASE f.data->'policy'->>'benefit'WHEN'CN_UNPAID'THEN'LEAVE_PAY_RECONCILIATION'WHEN'HK_UNPAID'THEN'LEAVE_PAY_RECONCILIATION'WHEN'CN_SICK'THEN'CN_SICK_PAY'WHEN'CN_PAID'THEN'CN_PAID_LEAVE_PAY'WHEN'CN_MATERNITY'THEN'CN_MATERNITY_TOPUP'WHEN'HK_ANNUAL'THEN'HK_ANNUAL_LEAVE_PAY'WHEN'HK_SICK'THEN'HK_SICKNESS_ALLOWANCE'WHEN'HK_MATERNITY'THEN'HK_MATERNITY_PAY'WHEN'HK_PATERNITY'THEN'HK_PATERNITY_PAY'END END;
 SELECT c.*INTO rel FROM public.ty_pay_row rr JOIN public.ty_pay_config c ON c.id=rr.relationship_config_id WHERE rr.id=i.row_id;
 IF a.source_domain<>'leave_pay'OR NOT coalesce(public.fn_ty_lp_current(f.id),false)OR part NOT IN('pay','reduction')OR p.group_id<>b.group_id OR p.company_id<>b.company_id OR p.person_id IS DISTINCT FROM o.person_id OR p.employment_id IS DISTINCT FROM o.employment_id OR p.period<>b.period OR f.currency<>b.currency OR f.system<>b.system OR i.code IS DISTINCT FROM code OR rel.data->>'actual_employer_key'IS DISTINCT FROM f.data->'request'->>'legal_employer_key'OR a.source_revision<>(f.revision||':'||p.head_revision)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='普通假期给薪须反查当前已核版本、实际请假、雇主、人员、期间、项目和币种';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.ty_pay_adoption pair WHERE pair.batch_id=b.id AND pair.source_domain='leave_pay'AND split_part(pair.source_id,':',1)=f.id::text AND split_part(pair.source_id,':',2)=CASE part WHEN'pay'THEN'reduction'ELSE'pay'END AND pair.state IN('reserved','confirmed'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='给薪与普通工资差减须成对核对，不能遗漏另一部分';END IF;RETURN'leave_pay:'||p.id||':'||part;END;$$;
CREATE FUNCTION fn_ty_lp_pay_expected(batch_key bigint,adoption_key bigint)RETURNS numeric LANGUAGE plpgsql STABLE SET search_path=''AS $$DECLARE a public.ty_pay_adoption%ROWTYPE;f public.ty_lp_fact%ROWTYPE;b public.ty_pay_batch%ROWTYPE;book public.ty_pay_config%ROWTYPE;i public.ty_pay_item%ROWTYPE;tags jsonb;BEGIN PERFORM public.fn_ty_lp_pay_key(batch_key,adoption_key);SELECT*INTO a FROM public.ty_pay_adoption WHERE id=adoption_key;SELECT*INTO f FROM public.ty_lp_fact WHERE id=split_part(a.source_id,':',1)::bigint;SELECT*INTO b FROM public.ty_pay_batch WHERE id=batch_key;SELECT*INTO book FROM public.ty_pay_config WHERE id=b.rulebook_id;SELECT*INTO i FROM public.ty_pay_item WHERE adoption_id=a.id;tags=book.data->'source_treatments'->'leave_pay'->i.code;IF tags?'wage_tags'THEN tags=tags->'wage_tags';END IF;IF tags IS NULL OR NOT(tags?'hk_adw'AND tags?'cn_average'AND tags?'cn_annual_leave'AND tags?'ordinary_wage')OR EXISTS(SELECT 1 FROM jsonb_each_text(tags)x WHERE x.value NOT IN('include','exclude','not_applicable'))OR NOT i.wage_tags@>tags THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='普通假期给薪法定工资窗口标签尚未核准';END IF;RETURN public.fn_ty_lp_amount_data(f.data,split_part(a.source_id,':',2));END;$$;
ALTER FUNCTION fn_ty_pay_extension_expected(bigint,bigint)RENAME TO fn_ty_pay_extension_expected_pre234;
ALTER FUNCTION fn_ty_pay_extension_key(bigint,bigint)RENAME TO fn_ty_pay_extension_key_pre234;
CREATE FUNCTION fn_ty_pay_extension_expected(batch_key bigint,adoption_key bigint)RETURNS numeric LANGUAGE plpgsql SET search_path=''AS $$BEGIN IF EXISTS(SELECT 1 FROM public.ty_pay_adoption WHERE id=adoption_key AND source_domain='leave_pay')THEN RETURN public.fn_ty_lp_pay_expected(batch_key,adoption_key);END IF;RETURN public.fn_ty_pay_extension_expected_pre234(batch_key,adoption_key);END;$$;
CREATE FUNCTION fn_ty_pay_extension_key(batch_key bigint,adoption_key bigint)RETURNS text LANGUAGE plpgsql SET search_path=''AS $$BEGIN IF EXISTS(SELECT 1 FROM public.ty_pay_adoption WHERE id=adoption_key AND source_domain='leave_pay')THEN RETURN public.fn_ty_lp_pay_key(batch_key,adoption_key);END IF;RETURN public.fn_ty_pay_extension_key_pre234(batch_key,adoption_key);END;$$;
DO $$DECLARE f text;definition text;needle text='IN(''statutory_calculation'',''performance_award'',''training_award'')';BEGIN FOREACH f IN ARRAY ARRAY['fn_ty_pay_authority_guard()','fn_ty_pay_reverse_provenance()']LOOP SELECT pg_get_functiondef(('public.'||f)::regprocedure)INTO definition;IF strpos(definition,needle)=0 THEN RAISE EXCEPTION '234 prerequisite payroll extension dispatch changed';END IF;EXECUTE replace(definition,needle,'IN(''statutory_calculation'',''performance_award'',''training_award'',''leave_pay'')');END LOOP;END$$;
-- A full monthly wage calculation cannot omit an already-taken ordinary leave
-- fact. Source-only supplementary/correction batches retain their exact scope.
CREATE FUNCTION fn_ty_lp_batch_completeness()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE r record;request_key bigint;f bigint;BEGIN
 IF NEW.status<>'confirmed'OR OLD.status='confirmed'THEN RETURN NEW;END IF;
 FOR r IN SELECT DISTINCT row.employment_id FROM public.ty_pay_row row JOIN public.ty_pay_item i ON i.row_id=row.id JOIN public.ty_pay_adoption a ON a.id=i.adoption_id WHERE row.batch_id=NEW.id AND a.source_domain='payroll_calculation'LOOP
  FOR request_key IN SELECT id FROM public.ty_leave_request WHERE employment_id=r.employment_id AND status='taken'AND starts_at<((NEW.period+interval '1 month')AT TIME ZONE 'Asia/Shanghai')AND ends_at>(NEW.period::timestamp AT TIME ZONE 'Asia/Shanghai')LOOP
   SELECT p.current_approved_id INTO f FROM public.ty_lp_parent p WHERE p.request_id=request_key AND p.period=NEW.period;
   IF f IS NULL OR NOT coalesce(public.fn_ty_lp_current(f),false)OR(SELECT count(DISTINCT split_part(source_id,':',2))FROM public.ty_pay_adoption WHERE batch_id=NEW.id AND source_domain='leave_pay'AND split_part(source_id,':',1)=f::text AND split_part(source_id,':',2)IN('pay','reduction')AND state IN('reserved','confirmed'))<>2 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='完整月工资不得遗漏当期已休假期的已核给薪及正常工资覆盖差减';END IF;
  END LOOP;
 END LOOP;RETURN NEW;END;$$;
CREATE TRIGGER ty_lp_batch_completeness BEFORE UPDATE ON ty_pay_batch FOR EACH ROW EXECUTE FUNCTION fn_ty_lp_batch_completeness();
